CREATE TABLE IF NOT EXISTS roles(id SERIAL PRIMARY KEY,name VARCHAR(30) UNIQUE NOT NULL);
INSERT INTO roles(name) VALUES('learner'),('teacher'),('admin') ON CONFLICT DO NOTHING;

CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role_id INT REFERENCES roles(id),is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS learner_profiles(id BIGSERIAL PRIMARY KEY,user_id BIGINT UNIQUE REFERENCES users(id) ON DELETE CASCADE,school_name VARCHAR(180),education_level VARCHAR(80),avatar_url TEXT);
CREATE TABLE IF NOT EXISTS teacher_profiles(id BIGSERIAL PRIMARY KEY,user_id BIGINT UNIQUE REFERENCES users(id) ON DELETE CASCADE,bio TEXT,qualification VARCHAR(180));
CREATE TABLE IF NOT EXISTS subjects(id SERIAL PRIMARY KEY,name VARCHAR(80) UNIQUE NOT NULL,slug VARCHAR(100) UNIQUE NOT NULL,description TEXT,color VARCHAR(30));
CREATE TABLE IF NOT EXISTS courses(id BIGSERIAL PRIMARY KEY,subject_id INT REFERENCES subjects(id),title VARCHAR(180) NOT NULL,slug VARCHAR(180) UNIQUE NOT NULL,description TEXT,is_premium BOOLEAN DEFAULT TRUE,published BOOLEAN DEFAULT FALSE,created_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS topics(id BIGSERIAL PRIMARY KEY,subject_id INT REFERENCES subjects(id) ON DELETE CASCADE,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL,description TEXT,UNIQUE(subject_id,slug));
CREATE TABLE IF NOT EXISTS lessons(id BIGSERIAL PRIMARY KEY,topic_id BIGINT REFERENCES topics(id) ON DELETE CASCADE,title VARCHAR(200) NOT NULL,slug VARCHAR(220) UNIQUE NOT NULL,content_html TEXT NOT NULL,duration_minutes INT DEFAULT 20,level VARCHAR(50) DEFAULT 'Secondary',is_premium BOOLEAN DEFAULT TRUE,published BOOLEAN DEFAULT TRUE,created_by BIGINT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS lesson_resources(id BIGSERIAL PRIMARY KEY,lesson_id BIGINT REFERENCES lessons(id) ON DELETE CASCADE,title VARCHAR(180),type VARCHAR(30),url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS articles(id BIGSERIAL PRIMARY KEY,title VARCHAR(220),slug VARCHAR(240) UNIQUE,excerpt TEXT,content_html TEXT,subject_id INT REFERENCES subjects(id),author_id BIGINT REFERENCES users(id),status VARCHAR(30) DEFAULT 'draft',published_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS quizzes(id BIGSERIAL PRIMARY KEY,title VARCHAR(220),description TEXT,course_id BIGINT REFERENCES courses(id),is_published BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS questions(id BIGSERIAL PRIMARY KEY,quiz_id BIGINT REFERENCES quizzes(id) ON DELETE CASCADE,prompt TEXT NOT NULL,options JSONB NOT NULL,correct_option INT NOT NULL,position INT NOT NULL);
CREATE TABLE IF NOT EXISTS quiz_attempts(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),quiz_id BIGINT REFERENCES quizzes(id),score INT,answers JSONB,started_at TIMESTAMPTZ DEFAULT NOW(),completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS exams(id BIGSERIAL PRIMARY KEY,title VARCHAR(220),description TEXT,duration_minutes INT,course_id BIGINT REFERENCES courses(id),is_published BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS exam_attempts(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),exam_id BIGINT REFERENCES exams(id),score INT,answers JSONB,started_at TIMESTAMPTZ DEFAULT NOW(),submitted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS enrollments(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),course_id BIGINT REFERENCES courses(id),status VARCHAR(30) DEFAULT 'active',enrolled_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,course_id));
CREATE TABLE IF NOT EXISTS progress(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),lesson_id BIGINT REFERENCES lessons(id),percent INT DEFAULT 0,completed BOOLEAN DEFAULT FALSE,updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,lesson_id));
CREATE TABLE IF NOT EXISTS subscriptions(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),plan VARCHAR(20) NOT NULL,status VARCHAR(30) NOT NULL,current_period_start TIMESTAMPTZ,current_period_end TIMESTAMPTZ,provider VARCHAR(30),provider_subscription_id TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),amount NUMERIC(12,2),currency VARCHAR(10),provider VARCHAR(30),provider_reference TEXT,status VARCHAR(30),paid_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bookmarks(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),lesson_id BIGINT REFERENCES lessons(id),created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,lesson_id));
CREATE TABLE IF NOT EXISTS reviews(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),course_id BIGINT REFERENCES courses(id),rating INT CHECK(rating BETWEEN 1 AND 5),comment TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,course_id));
CREATE TABLE IF NOT EXISTS notifications(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),title VARCHAR(180),body TEXT,is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS live_classes(id BIGSERIAL PRIMARY KEY,title VARCHAR(220),description TEXT,teacher_id BIGINT REFERENCES users(id),subject_id INT REFERENCES subjects(id),starts_at TIMESTAMPTZ,ends_at TIMESTAMPTZ,meeting_url TEXT,status VARCHAR(30) DEFAULT 'scheduled');
CREATE TABLE IF NOT EXISTS certificates(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),course_id BIGINT REFERENCES courses(id),certificate_number VARCHAR(100) UNIQUE,issued_at TIMESTAMPTZ DEFAULT NOW(),pdf_url TEXT);
CREATE TABLE IF NOT EXISTS password_resets(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),token_hash TEXT,expires_at TIMESTAMPTZ,used_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_lessons_topic ON lessons(topic_id);
CREATE INDEX IF NOT EXISTS idx_topics_subject ON topics(subject_id);
CREATE INDEX IF NOT EXISTS idx_subscriptions_user_status ON subscriptions(user_id,status,current_period_end);
CREATE INDEX IF NOT EXISTS idx_payments_user ON payments(user_id,created_at);
